llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C22"],
      "claim": "Brigatinib, a highly transferable analogue sharing a basic piperidine and heteroaromatic core, has an absolute oral bioavailability of 46% in healthy volunteers, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Paliperidone, structurally similar through a fused heteroaromatic lactam and piperidine, has an absolute oral bioavailability of 28% in healthy volunteers, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Alizapride, a polar basic heteroaromatic amide, has an absolute oral bioavailability of 72.5%, supporting the possibility of high oral absorption despite polar/ionizable features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Fexofenadine, a polar/ionized drug with transporter involvement, has an absolute oral bioavailability of 30–40% in humans, supporting F ≥ 20% for challenging permeability profiles.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "LY2196044, a pyridine/piperidine-containing drug, has an estimated absolute oral bioavailability of 45%, supporting a high prediction for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "UK-224,671, a piperidine/piperazine lactam, has low absolute oral bioavailability of 7.5% in humans, providing contradictory evidence for a low outcome.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C37"],
      "claim": "Lurasidone, a piperazine-fused imide, has only 10% oral bioavailability in the fasted state, arguing that some related basic heteroaromatic drugs can have low F.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C07"],
      "claim": "SRT2104, a heteroaromatic amide, has an absolute oral bioavailability of 13.8%, providing additional contradictory evidence for a low outcome.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The high-transfer supportive evidence from brigatinib, paliperidone, alizapride, fexofenadine, and LY2196044—many sharing piperidine and heteroaromatic/lactam features with the query—outweighs the lower-F analogues, whose specific liabilities (sulfamide, high lipophilicity/first-pass metabolism, poor solubility) are less applicable. The unfavorable physicochemical prior is low-confidence and does not override direct human absolute bioavailability evidence from transferable analogues.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "Conflicting low-F analogues with similar polar/basic features create uncertainty.",
    "Unknown contributions of efflux transporters and first-pass metabolism for the query.",
    "Computed physicochemical prior is low confidence and not experimentally validated."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

